reference_solution:
def flight_booking_totals(bookings, n):
 difference=[0]*(n+1)
 for first,last,seats in bookings:
  difference[first-1]+=seats
  if last<n:difference[last]-=seats
 answer=[];running=0
 for i in range(n):running+=difference[i];answer.append(running)
 return answer

